#!/usr/bin/env node
// Generates TypeScript types from each contract's committed ABI (docs/SDK.md "Type generation").
//   node scripts/gen-abi-types.mjs          write packages/sdk/src/generated/*.ts
//   node scripts/gen-abi-types.mjs --check  exit 1 if a generated file differs from the ABI
// The ABI files are produced by `cargo near abi` in contracts/<name> and committed in res/. No
// dependencies: the ABIs use only the small JSON Schema subset mapped below, and an unknown keyword
// fails the run instead of being silently dropped.
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const CONTRACTS = ["vault", "registry", "pool"];
const OUT = join(root, "packages/sdk/src/generated");

const KNOWN = new Set(["type", "format", "minimum", "maximum", "description", "$ref", "anyOf", "oneOf", "allOf", "enum", "properties", "required", "items", "minItems", "maxItems", "additionalProperties", "default", "title", "$schema", "definitions"]);

function ts(s, where) {
  if (s === true || (typeof s === "object" && s !== null && Object.keys(s).length === 0)) return "unknown"; // the ABI's "any value", e.g. a Promise result
  for (const k of Object.keys(s)) if (!KNOWN.has(k)) throw new Error(`${where}: unsupported schema keyword "${k}"`);
  if (s.$ref) return s.$ref.replace("#/definitions/", "");
  if (s.allOf) return s.allOf.length === 1 ? ts(s.allOf[0], where) : s.allOf.map((x) => ts(x, where)).join(" & ");
  if (s.anyOf) return [...new Set(s.anyOf.map((x) => ts(x, where)))].join(" | ");
  if (s.oneOf) return [...new Set(s.oneOf.map((x) => ts(x, where)))].join(" | ");
  if (s.enum) return s.enum.map((v) => JSON.stringify(v)).join(" | ");
  const t = s.type;
  if (Array.isArray(t)) return t.map((x) => ts({ ...s, type: x }, where)).join(" | ");
  switch (t) {
    case "string": return "string";
    case "integer": case "number": return "number";
    case "boolean": return "boolean";
    case "null": return "null";
    case "array":
      if (Array.isArray(s.items)) return `[${s.items.map((x) => ts(x, where)).join(", ")}]`;
      if (s.minItems !== undefined && s.minItems === s.maxItems) return `[${Array(s.minItems).fill(ts(s.items, where)).join(", ")}]`;
      return `${wrap(ts(s.items, where))}[]`;
    case "object": {
      const req = new Set(s.required ?? []);
      const props = Object.entries(s.properties ?? {}).sort(([a], [b]) => a.localeCompare(b));
      return `{ ${props.map(([k, v]) => `${/^[A-Za-z_]\w*$/.test(k) ? k : JSON.stringify(k)}${req.has(k) ? "" : "?"}: ${ts(v, `${where}.${k}`)};`).join(" ")} }`;
    }
    default:
      throw new Error(`${where}: cannot map schema ${JSON.stringify(s).slice(0, 120)}`);
  }
}
const wrap = (t) => (/[|&]/.test(t) ? `(${t})` : t);
const pascal = (s) => s.split("_").map((w) => w[0].toUpperCase() + w.slice(1)).join("");

function generate(name) {
  const abi = JSON.parse(readFileSync(join(root, `contracts/${name}/res/aruna_${name}.abi.json`), "utf8"));
  const defs = abi.body.root_schema.definitions ?? {};
  const out = [`// GENERATED by scripts/gen-abi-types.mjs from contracts/${name}/res/aruna_${name}.abi.json. Do not edit.`, ""];
  for (const k of Object.keys(defs).sort()) out.push(`export type ${pascal(name)}${k} = ${ts(defs[k], k)};`);
  out.push("");
  const fns = [...abi.body.functions].sort((a, b) => a.name.localeCompare(b.name));
  const entries = fns.map((f) => {
    const args = (f.params?.args ?? []).map((a) => `${a.name}: ${ts(a.type_schema, f.name)}`).join("; ");
    const result = f.result ? ts(f.result.type_schema, f.name) : "null";
    return `  ${f.name}: { kind: ${JSON.stringify(f.kind)}; payable: ${(f.modifiers ?? []).includes("payable")}; args: { ${args} }; result: ${result} };`;
  });
  out.push(`export interface ${pascal(name)}Methods {`, ...entries, "}", "");
  out.push(`export const ${name.toUpperCase()}_METHODS = ${JSON.stringify(fns.map((f) => f.name))} as const;`, "");
  // Qualify definition names inside method signatures with the contract prefix.
  let body = out.join("\n");
  const P = pascal(name);
  const names = Object.keys(defs).sort((a, b) => b.length - a.length);
  const split = body.indexOf(`export interface ${P}Methods`);
  let tail = body.slice(split);
  for (const n of names) tail = tail.replace(new RegExp(`(?<![\\w.])${n}(?!\\w)`, "g"), `${P}${n}`);
  let head = body.slice(0, split);
  for (const n of names) head = head.replace(new RegExp(`(?<=[:|&(\\[] )${n}(?=[ ;|&)\\[\\]])`, "g"), `${P}${n}`);
  return head + tail;
}

let stale = false;
mkdirSync(OUT, { recursive: true });
for (const c of CONTRACTS) {
  const file = join(OUT, `${c}.ts`);
  const text = generate(c);
  if (process.argv.includes("--check")) {
    if (!existsSync(file) || readFileSync(file, "utf8") !== text) { console.error(`stale: ${file}; run node scripts/gen-abi-types.mjs`); stale = true; }
  } else writeFileSync(file, text);
}
process.exit(stale ? 1 : 0);
